frame.store("_with_its_y_back", { let __signature_4420 = Signature { name: "_with_its_y_back".into(), positional: vec!["stem".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_4422 = Value::dict(); __attrs_4422.dict_set(Value::from("__doc__"), Value::from("The y a comparison turned into an i: \"happi\" is \"happy\", \"angri\" is \"angry\".\n\n    English writes -ier and -iest on a state that ends in y (happy, happier, happiest), so the\n    stem of the comparison is one letter off the word it was made from. Only an i is put back,\n    because that is the only letter the ending ever changes.\n    "))?; __attrs_4422.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_4423 = Value::dict(); __attrs_4422.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_4419 = Frame::module(frame.globals.clone()); let mut __function_4421 = NativeFunction::qualified_with_attrs("_with_its_y_back".into(), "_with_its_y_back".into(), "bot.memory.facts".into(), __attrs_4422, move |rt, args| __py_85::_with_its_y_back(rt, __closure_4419.clone(), &__signature_4420, args)); __function_4421 })?;
